<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import type { ReleaseDraft, ManagedRelease } from '../shared/admin'
import { maxPackageBytes } from '../shared/admin'
import { guideApi, uploadFile } from './guide-api'
import WebsiteDialog from './WebsiteDialog.vue'
const props=defineProps<{csrf:string}>()
const emit=defineEmits<{error:[e:unknown];dirty:[v:boolean];busy:[v:boolean]}>()
const drafts=ref<ReleaseDraft[]>([]),releases=ref<ManagedRelease[]>([]),current=ref<ReleaseDraft>(),published=ref<ManagedRelease>()
const form=ref({version:'',platform:'windows-x64',title:'',changelog:'',enabled:true}),baseline=ref(''),busy=ref(false),creating=ref(false),notice=ref(''),progress=ref(0),uploadName=ref(''),fileInput=ref<HTMLInputElement>()
const confirmation=ref<{title:string;message:string;label?:string;action:()=>void}>()
const lifetime=new AbortController();let upload:AbortController|undefined
const dirty=computed(()=>Boolean(current.value||published.value||creating.value)&&JSON.stringify(form.value)!==baseline.value)
watch(dirty,v=>emit('dirty',v));watch(busy,v=>emit('busy',v))
const call=<T,>(url:string,options:{method?:string;data?:unknown;timeout?:number}={})=>guideApi<T>(url,{...options,csrf:props.csrf,signal:lifetime.signal})
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;notice.value='';try{await fn()}catch(e){emit('error',e)}finally{busy.value=false}}
async function list(){const result=await call<{drafts:ReleaseDraft[];releases:ManagedRelease[]}>('/api/admin/releases');drafts.value=result.drafts;releases.value=result.releases}
function adopt(value:ReleaseDraft|ManagedRelease){creating.value=false;if('id'in value){current.value=value;published.value=undefined}else{published.value=value;current.value=undefined}form.value={version:value.version,platform:'platform'in value?value.platform:'windows-x64',title:value.title,changelog:value.notes.join('\n'),enabled:'enabled'in value?value.enabled:true};baseline.value=JSON.stringify(form.value)}
function guard(action:()=>void){if(busy.value)return;if(dirty.value)confirmation.value={title:'放弃未保存的修改？',message:'已上传的文件仍保留在草稿中。',label:'放弃修改',action};else action()}
function create(){guard(()=>{current.value=undefined;published.value=undefined;creating.value=true;form.value={version:'',platform:'windows-x64',title:'',changelog:'',enabled:true};baseline.value=JSON.stringify(form.value);notice.value=''})}
function notes(){return form.value.changelog.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
async function save(){await run(async()=>{
  if(published.value){const result=await call<{release:ManagedRelease}>(`/api/admin/releases/published/${encodeURIComponent(published.value.version)}`,{method:'PUT',data:{release:{title:form.value.title,notes:notes(),enabled:form.value.enabled},revision:published.value.revision}});adopt(result.release)}
  else{const id=current.value?.id;const result=await call<{draft:ReleaseDraft}>(id?`/api/admin/releases/drafts/${id}`:'/api/admin/releases',{method:id?'PUT':'POST',data:{draft:{version:form.value.version,platform:form.value.platform,title:form.value.title,notes:notes()},revision:current.value?.revision}});adopt(result.draft)}
  await list();notice.value=published.value?'更新说明和显示状态已保存。':'草稿已保存，可以上传安装包。'
})}
function saveClick(){if(published.value&&published.value.enabled&&!form.value.enabled)confirmation.value={title:'下架这个版本？',message:'下载页和自动更新将不再提供这个版本，归档文件仍保留。',label:'保存并下架',action:()=>void save()};else void save()}
async function send(event:Event){const files=Array.from((event.target as HTMLInputElement).files??[]);if(!current.value||!files.length)return;await run(async()=>{upload=new AbortController();try{for(const file of files){if(file.size>maxPackageBytes){notice.value=`${file.name} 超过 2 GiB，请使用发布命令处理更大的软件包。`;break}uploadName.value=file.name;progress.value=0;const result=await uploadFile<{draft:ReleaseDraft}>(`/api/admin/releases/drafts/${current.value!.id}/files?name=${encodeURIComponent(file.name)}`,file,{csrf:props.csrf,revision:current.value!.revision,signal:upload.signal,progress:v=>progress.value=v});adopt(result.draft)}await list();if(!notice.value)notice.value='上传完成，请核对清单和更新说明后发布。'}catch(e){if(upload.signal.aborted)notice.value='上传已取消，已完成的文件仍保留。';else throw e}finally{uploadName.value='';if(fileInput.value)fileInput.value.value=''}})}
function removeFile(name:string){confirmation.value={title:'移除这个草稿文件？',message:name,label:'移除文件',action:()=>void run(async()=>{adopt((await call<{draft:ReleaseDraft}>(`/api/admin/releases/drafts/${current.value!.id}/files?name=${encodeURIComponent(name)}`,{method:'DELETE',data:{revision:current.value!.revision}})).draft);await list()})}}
function discard(){confirmation.value={title:'将发布草稿移至回收目录？',message:'已发布的版本和安装包不会受影响。',label:'移除草稿',action:()=>void run(async()=>{await call(`/api/admin/releases/drafts/${current.value!.id}`,{method:'DELETE',data:{revision:current.value!.revision}});current.value=undefined;await list();notice.value='草稿已移至回收目录。'})}}
function publish(){const d=current.value;if(!d)return;confirmation.value={title:`发布 ${d.version}？`,message:`${d.platform==='windows-x64'?'Windows x64':'macOS Apple 芯片'} · ${d.files.length} 个文件。发布后会出现在下载页并参与自动更新。请确认下方文件清单和更新说明正确，安装包发布后不可覆盖。`,label:'确认发布',action:()=>void run(async()=>{await call(`/api/admin/releases/drafts/${d.id}/publish`,{method:'POST',data:{revision:d.revision},timeout:30*60*1000});await list();adopt(releases.value.find(r=>r.version===d.version)!);notice.value='发布成功，下载页和自动更新已更新。'})}}
function reload(){guard(()=>void run(async()=>{const id=current.value?.id,version=published.value?.version;await list();const value=id?drafts.value.find(d=>d.id===id):releases.value.find(r=>r.version===version);if(value)adopt(value);else{current.value=undefined;published.value=undefined;creating.value=false}}))}
function accept(){const action=confirmation.value?.action;confirmation.value=undefined;action?.()}
function size(bytes:number){if(bytes<1024)return `${bytes} B`;if(bytes<1024**2)return `${(bytes/1024).toFixed(1)} KiB`;return bytes>=1024**3?`${(bytes/1024**3).toFixed(2)} GiB`:`${(bytes/1024**2).toFixed(2)} MiB`}
const publishedFiles=computed(()=>Object.entries(published.value?.targets??{}).flatMap(([platform,target])=>target!.downloads.map(f=>({...f,platform}))))
onMounted(()=>run(list));onBeforeUnmount(()=>{lifetime.abort();upload?.abort();emit('dirty',false);emit('busy',false)})
</script>
<template><section :aria-busy="busy"><div class="editor-heading"><div><h2>发布包管理</h2><p>上传安装包，维护更新说明，再确认发布。</p></div><div class="admin-actions"><button class="button secondary" :disabled="busy" @click="reload">刷新列表</button><button class="button primary" :disabled="busy" @click="create">新建发布</button></div></div><p v-if="notice" class="admin-success" role="status">{{notice}}</p><div class="admin-layout"><aside class="admin-sidebar release-sidebar"><h3>发布草稿</h3><p v-if="!drafts.length" class="editor-help">尚无草稿</p><nav aria-label="发布草稿"><button v-for="d in drafts" :key="d.id" :disabled="busy" :aria-current="current?.id===d.id?'page':undefined" @click="guard(()=>adopt(d))"><span>{{d.version}} · {{d.platform==='windows-x64'?'Windows':'macOS'}}</span><small>{{d.published?'已发布，可清理草稿':`${d.files.length} 个文件 · 待发布`}}</small></button></nav><h3>已发布版本</h3><p v-if="!releases.length" class="editor-help">尚未发布版本</p><nav aria-label="已发布版本"><button v-for="r in releases" :key="r.version" :disabled="busy" :aria-current="published?.version===r.version?'page':undefined" @click="guard(()=>adopt(r))"><span>{{r.version}} · {{r.title}}</span><small>{{r.enabled?'已上架':'已下架'}} · {{new Date(r.publishedAt).toLocaleDateString()}}</small></button></nav></aside><section v-if="current||published||creating" class="admin-workspace release-workspace"><div class="editor-heading"><h3>{{published?'维护已发布版本':current?'发布草稿':'创建发布草稿'}}</h3><span class="editor-help">{{dirty?'有未保存的修改':creating?'尚未创建':'已保存'}}</span></div><form @submit.prevent="saveClick"><fieldset :disabled="busy||current?.published"><div class="chapter-fields"><label>版本号<input v-model="form.version" :disabled="!!published||!!current?.files.length" placeholder="例如：1.2.3" required maxlength="80" /></label><label>版本标题<input v-model="form.title" required maxlength="120" placeholder="例如：工作效率更新" /></label></div><fieldset v-if="!published" class="platform-choices" :disabled="!!current?.files.length"><legend>发布平台</legend><label class="check-label"><input v-model="form.platform" type="radio" value="windows-x64" />Windows x64</label><label class="check-label"><input v-model="form.platform" type="radio" value="macos-arm64" />macOS Apple 芯片</label></fieldset><label class="release-notes">更新说明 / Changelog<textarea v-model="form.changelog" required rows="7" maxlength="30030" placeholder="每行一条更新说明，例如：&#10;新增文档图片上传&#10;优化工作台启动速度"></textarea><small>每行一条，共 1–30 条，每条最多 1000 字。多个平台共享同版本的说明。</small></label><label v-if="published" class="check-label"><input v-model="form.enabled" type="checkbox" />在下载页与自动更新中提供此版本</label><button class="button primary" :disabled="busy||(!dirty&&!creating)||current?.published">{{busy?'处理中…':published?'保存版本信息':'保存草稿'}}</button></fieldset></form><template v-if="current"><div class="editor-heading package-upload"><div><h3>软件包</h3><p>单文件最多 2 GiB，每个平台最多 8 个文件。</p></div><div class="admin-actions"><input ref="fileInput" class="file-input" type="file" accept=".exe,.zip,.dmg,.blockmap" multiple aria-label="选择软件包文件" :disabled="busy||dirty||current.published" @change="send" /><button class="button secondary" :disabled="busy||dirty||current.published" @click="fileInput?.click()">上传软件包</button><button v-if="uploadName" class="button secondary" @click="upload?.abort()">取消上传</button></div></div><p class="editor-help">{{current.platform==='windows-x64'?`主文件示例：Office-${current.version}-x64.exe`:`主文件示例：Office-${current.version}-arm64.zip；可附加同版本 arm64.dmg`}}。请保留实际构建产物的版本和架构命名。</p><div v-if="uploadName" class="upload-progress" role="status"><span>{{uploadName}}</span><progress :value="progress" max="100"></progress>{{progress}}% · {{progress===100?'正在校验保存…':'上传中'}}</div><p v-if="!current.files.length" class="admin-empty">保存草稿后上传安装包。</p><article v-for="file in current.files" :key="file.name" class="package-file"><div><strong>{{file.name}}</strong><small>{{size(file.size)}}</small><details><summary>SHA-512 校验和</summary><code>{{file.sha512}}</code></details></div><button v-if="!current.published" :disabled="busy||dirty" @click="removeFile(file.name)">移除</button></article><div class="editor-bottom"><button :disabled="busy" @click="discard">移除草稿</button><button class="button primary" :disabled="busy||dirty||!current.files.length||current.published" @click="publish">{{current.published?'已发布':'核对并发布'}}</button></div></template><template v-if="published"><div class="package-upload"><h3>已发布安装包</h3><p class="editor-help">安装包不可覆盖。如需替换，请创建新版本。</p><article v-for="file in publishedFiles" :key="file.platform+file.name" class="package-file"><div><strong>{{file.name}}</strong><small>{{file.platform}} · {{size(file.size)}}</small><details><summary>SHA-512 校验和</summary><code>{{file.sha512}}</code></details></div><a v-if="published.enabled" :href="`/updates/archive/${published.version}/${file.platform}/${encodeURIComponent(file.name)}`" download>下载</a></article></div></template></section><div v-else class="admin-empty">新建发布，或选择左侧的草稿和版本。</div></div><WebsiteDialog v-if="confirmation" :title="confirmation.title" :message="confirmation.message" :confirm-label="confirmation.label" @cancel="confirmation=undefined" @confirm="accept"><div v-if="confirmation.label==='确认发布'" class="release-review"><h3>{{current?.title}}</h3><ul><li v-for="note in current?.notes" :key="note">{{note}}</li></ul><p v-for="file in current?.files" :key="file.name">{{file.name}} · {{size(file.size)}}</p></div></WebsiteDialog></section></template>
